-- FitLogix: full database setup for a NEW Supabase project. Generated by `npm run sql:setup`; do not edit by hand.
-- Supabase: SQL Editor -> New query -> paste this whole file -> Run. Safe to run again.
-- Existing projects: run only the update-*.sql files you have not run yet (the admin area lists them).
-- Afterwards: make yourself admin (bottom of admin.sql) and, for reminders, run update-5b-schedule-reminders.sql.

-- ===================== schema.sql =====================

-- FitLogix schema. Run once in Supabase: SQL Editor -> New query -> paste -> Run.
-- Every table has the same shape (id, user_id, created_at + data columns),
-- and Row Level Security makes each user see only their own rows.

create table if not exists public.profiles (
  id text primary key,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  display_name text,
  first_name text,
  last_name text,
  age int,
  birth_date date,
  gender text check (gender in ('male', 'female')),
  height_cm int,
  experience text,
  fitness_goal text,
  training_days int,
  training_locations jsonb,
  equipment jsonb,
  onboarded_at timestamptz,
  active_program_id text,
  calorie_goal int not null default 2200,
  protein_goal int not null default 140,
  carbs_goal int not null default 250,
  fat_goal int not null default 70,
  water_goal int not null default 8,
  weight_goal numeric
);

create table if not exists public.workouts (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  date date not null,
  name text not null,
  notes text,
  duration_min int,
  exercises jsonb not null default '[]',
  program_id text,
  program_day int
);

create table if not exists public.programs (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  name text not null,
  days jsonb not null default '[]',
  schedule jsonb
);

create table if not exists public.meals (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  date date not null,
  meal_type text not null default 'snack',
  name text not null,
  calories int not null default 0,
  protein numeric not null default 0,
  carbs numeric not null default 0,
  fat numeric not null default 0
);

create table if not exists public.body_weights (
  id text primary key default gen_random_uuid()::text,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  date date not null,
  weight numeric not null
);

create table if not exists public.water_logs (
  id text primary key,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  date date not null,
  glasses int not null default 0
);

do $$
declare t text;
begin
  foreach t in array array['profiles','workouts','programs','meals','body_weights','water_logs'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "own rows" on public.%I', t);
    execute format(
      'create policy "own rows" on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid())', t);
    execute format('create index if not exists %I on public.%I (user_id)', t || '_user_idx', t);
  end loop;
end $$;

-- Newer Supabase projects don't grant table access to signed-in users by default.
-- RLS above still limits every user to their own rows.
grant usage on schema public to authenticated;
grant select, insert, update, delete on
  public.profiles, public.workouts, public.programs,
  public.meals, public.body_weights, public.water_logs
to authenticated;

-- ===================== admin.sql =====================

-- FitLogix admin area. Run once in Supabase: SQL Editor -> New query -> paste -> Run.
-- Then make yourself an admin with the line at the bottom of this file.

create table if not exists public.admins (
  user_id uuid primary key references auth.users on delete cascade,
  created_at timestamptz not null default now()
);
-- No policies on purpose: the table is only reachable through the functions below.
alter table public.admins enable row level security;

create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.admins where user_id = auth.uid()) $$;

-- Admins may read (not change) every user's data, to follow their progress.
do $$
declare t text;
begin
  foreach t in array array['profiles','workouts','programs','meals','body_weights','water_logs'] loop
    execute format('drop policy if exists "admins read all" on public.%I', t);
    execute format('create policy "admins read all" on public.%I for select using (public.is_admin())', t);
  end loop;
end $$;

-- All users with a short summary. Returns nothing for non-admins.
drop function if exists public.admin_list_users();
create function public.admin_list_users()
returns table (
  id uuid, email text, created_at timestamptz, last_sign_in_at timestamptz,
  banned boolean, is_admin boolean, display_name text,
  first_name text, last_name text, age int, birth_date date,
  workouts bigint, last_workout date, last_weight numeric
)
language sql stable security definer set search_path = public
as $$
  select
    u.id, u.email::text, u.created_at, u.last_sign_in_at,
    coalesce(u.banned_until > now(), false),
    exists (select 1 from public.admins a where a.user_id = u.id),
    p.display_name, p.first_name, p.last_name, p.age, p.birth_date,
    (select count(*) from public.workouts w where w.user_id = u.id),
    (select max(w.date) from public.workouts w where w.user_id = u.id),
    (select b.weight from public.body_weights b where b.user_id = u.id order by b.date desc limit 1)
  from auth.users u
  left join lateral (
    select * from public.profiles pr where pr.user_id = u.id limit 1
  ) p on true
  where public.is_admin()
  order by u.created_at desc
$$;

create or replace function public.admin_set_banned(target uuid, ban boolean)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;
  if target = auth.uid() then raise exception 'cannot block yourself'; end if;
  update auth.users
     set banned_until = case when ban then now() + interval '100 years' else null end
   where id = target;
end $$;

create or replace function public.admin_set_admin(target uuid, make boolean)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;
  if target = auth.uid() and not make then raise exception 'cannot remove yourself as admin'; end if;
  if make then
    insert into public.admins (user_id) values (target) on conflict do nothing;
  else
    delete from public.admins where user_id = target;
  end if;
end $$;

-- Deletes the account and, through "on delete cascade", all of its data.
create or replace function public.admin_delete_user(target uuid)
returns void
language plpgsql security definer set search_path = public
as $$
begin
  if not public.is_admin() then raise exception 'not authorized'; end if;
  if target = auth.uid() then raise exception 'cannot delete yourself'; end if;
  delete from auth.users where id = target;
end $$;

revoke execute on function public.is_admin(), public.admin_list_users(),
  public.admin_set_banned(uuid, boolean), public.admin_set_admin(uuid, boolean),
  public.admin_delete_user(uuid) from public, anon;
grant execute on function public.is_admin(), public.admin_list_users(),
  public.admin_set_banned(uuid, boolean), public.admin_set_admin(uuid, boolean),
  public.admin_delete_user(uuid) to authenticated;

-- Make yourself the first admin (sign up in the app first, then put your email here):
-- insert into public.admins (user_id) select id from auth.users where email = 'YOUR-EMAIL';

-- ===================== update-2-signup.sql =====================

-- FitLogix update 2: sign-up details (first name, last name, age, birth date).
-- Run once in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again.

alter table public.profiles
  add column if not exists first_name text,
  add column if not exists last_name text,
  add column if not exists age int,
  add column if not exists birth_date date;

-- Create the profile from the details entered at sign-up. This runs inside Supabase,
-- so it works even when "Confirm email" is on and the user has no session yet.
-- Any bad value is skipped: it never blocks a sign-up.
create or replace function public.handle_new_user()
returns trigger
language plpgsql security definer set search_path = public
as $$
declare
  m jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
begin
  begin
    insert into public.profiles (id, user_id, first_name, last_name, display_name, age, birth_date)
    values (
      new.id::text, new.id,
      nullif(trim(m->>'first_name'), ''),
      nullif(trim(m->>'last_name'), ''),
      nullif(trim(m->>'first_name'), ''),
      case when m->>'age' ~ '^\d{1,3}$' then (m->>'age')::int end,
      case when m->>'birth_date' ~ '^\d{4}-\d{2}-\d{2}$' then (m->>'birth_date')::date end
    )
    on conflict (id) do nothing;
  exception when others then
    raise warning 'handle_new_user: %', sqlerrm;
  end;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Admin list now includes full name and age (return type changed, so drop first).
drop function if exists public.admin_list_users();
create function public.admin_list_users()
returns table (
  id uuid, email text, created_at timestamptz, last_sign_in_at timestamptz,
  banned boolean, is_admin boolean, display_name text,
  first_name text, last_name text, age int, birth_date date,
  workouts bigint, last_workout date, last_weight numeric
)
language sql stable security definer set search_path = public
as $$
  select
    u.id, u.email::text, u.created_at, u.last_sign_in_at,
    coalesce(u.banned_until > now(), false),
    exists (select 1 from public.admins a where a.user_id = u.id),
    p.display_name, p.first_name, p.last_name, p.age, p.birth_date,
    (select count(*) from public.workouts w where w.user_id = u.id),
    (select max(w.date) from public.workouts w where w.user_id = u.id),
    (select b.weight from public.body_weights b where b.user_id = u.id order by b.date desc limit 1)
  from auth.users u
  left join lateral (
    select * from public.profiles pr where pr.user_id = u.id limit 1
  ) p on true
  where public.is_admin()
  order by u.created_at desc
$$;
revoke execute on function public.admin_list_users() from public, anon;
grant execute on function public.admin_list_users() to authenticated;

-- ===================== update-3-onboarding.sql =====================

-- FitLogix update 3: training profile filled in after sign-up.
-- Run once in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again.

alter table public.profiles
  add column if not exists height_cm int,
  add column if not exists experience text,
  add column if not exists fitness_goal text,
  add column if not exists training_days int,
  add column if not exists training_locations jsonb,
  add column if not exists equipment jsonb,
  add column if not exists onboarded_at timestamptz;

-- ===================== update-4-schedule.sql =====================

-- FitLogix update 4: today's planned workout.
-- Run once in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again.

alter table public.workouts
  add column if not exists program_id text,
  add column if not exists program_day int;

alter table public.programs
  add column if not exists schedule jsonb;

alter table public.profiles
  add column if not exists active_program_id text;

-- ===================== update-5-reminders.sql =====================

-- FitLogix update 5: workout reminders (push notifications).
-- Run once in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again.

alter table public.profiles
  add column if not exists reminder_enabled boolean not null default false,
  add column if not exists reminder_time text,
  add column if not exists reminder_tz text,
  add column if not exists remind_training_day boolean not null default true,
  add column if not exists remind_no_workout boolean not null default true,
  add column if not exists last_reminded_on date;

-- One row per device that allowed notifications.
create table if not exists public.push_subscriptions (
  id text primary key,
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  created_at timestamptz not null default now(),
  endpoint text not null,
  p256dh text not null,
  auth text not null
);
alter table public.push_subscriptions enable row level security;
drop policy if exists "own rows" on public.push_subscriptions;
create policy "own rows" on public.push_subscriptions for all
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create index if not exists push_subscriptions_user_idx on public.push_subscriptions (user_id);
grant select, insert, update, delete on public.push_subscriptions to authenticated;

-- The reminder server uses the secret (service_role) key. It skips RLS, but newer Supabase
-- projects still require table privileges for it, like for signed-in users.
grant usage on schema public to service_role;
grant select, insert, update, delete on
  public.profiles, public.workouts, public.programs,
  public.meals, public.body_weights, public.water_logs,
  public.push_subscriptions
to service_role;

-- ===================== update-6-program-templates.sql =====================

-- FitLogix update 6: ready-made programs managed by admins from inside the app.
-- Run once in Supabase: SQL Editor -> New query -> paste -> Run. Safe to run again
-- (the starting programs are only added if they are not there yet).

create table if not exists public.program_templates (
  id text primary key default gen_random_uuid()::text,
  created_at timestamptz not null default now(),
  sort_order int not null default 0,
  name text not null,
  description text not null default '',
  category text not null check (category in ('gym', 'home', 'outdoor')),
  equipment text not null default '',
  schedule jsonb not null,
  days jsonb not null default '[]'
);

alter table public.program_templates enable row level security;
drop policy if exists "everyone reads" on public.program_templates;
create policy "everyone reads" on public.program_templates for select to authenticated using (true);
drop policy if exists "admins write" on public.program_templates;
create policy "admins write" on public.program_templates for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

grant select, insert, update, delete on public.program_templates to authenticated;
grant select, insert, update, delete on public.program_templates to service_role;

